def circular_shift(x, shift):
    if x < 0 or shift < 0:
        raise ValueError("x and shift must be non-negative integers")

    s = str(x)
    n = len(s)

    if shift > n:
        return s[::-1]

    shift = shift % n  # In case shift is greater than the number of digits
    return s[-shift:] + s[:-shift]

